AttachmentCanvasContainer: FC<AttachmentCanvasContainerProps> =
  memo(
    ({
      labels,
      isMobile = false,
      defaultWidth,
      maxWidth,
      codeBlockTheme,
      tableDownloadFilename,
      configurePdfWorker,
    }) => {
      const {
        ariaLabel = 'Attachment preview',
        closeLabel = 'Close',
        downloadLabel = 'Download',
        unsupportedLabel = 'Preview is not supported for this file',
        loadErrorLabel = 'Failed to load file',
        forbiddenErrorLabel = "You don't have permission to access this file",
        copyTextLabel,
        copiedTextLabel,
        copyMarkdownLabel,
        copiedMarkdownLabel,
        copyJsonLabel,
        copiedJsonLabel,
        htmlFrameBlockedLabel,
        htmlOpenInNewTabLabel,
        htmlViewSourceLabel,
        htmlViewRenderedLabel,
        pdfThumbnailsLabel,
        pdfShowThumbnailsLabel,
        pdfHideThumbnailsLabel,
        pdfPageNumberLabel,
        pdfContentLoadingLabel,
        pdfContentErrorLabel,
        pdfContentRetryLabel,
        xlsxFormulaLabel,
        codeContentLoadingLabel,
        codeContentErrorLabel,
        codeContentRetryLabel,
        tableCopyLabel,
        tableCopiedLabel,
        tableDownloadCsvLabel,
        ooxmlHighlightsLabel,
        ooxmlHighlightNavigatedLabel,
      } = labels ?? {};

      const { isOpen, isLoading, content, fileName, closeCanvas } =
        useAttachmentCanvas();

      const handleDownload = useCallback(() => {
        downloadAttachmentContent(content, fileName);
      }, [content, fileName]);

      const handleCopyText = useCallback(() => {
        if (content.type === AttachmentContentType.PlainText) {
          void copyToClipboard((content as PlainTextCanvasContent).text);
        } else if (content.type === AttachmentContentType.Code) {
          void copyToClipboard((content as CodeCanvasContent).text);
        }
      }, [content]);

      const handleCopyMarkdown = useCallback(() => {
        if (content.type === AttachmentContentType.Markdown) {
          void copyToClipboard((content as MarkdownCanvasContent).text);
        }
      }, [content]);

      const handleCopyJson = useCallback(() => {
        if (content.type === AttachmentContentType.Json) {
          void copyToClipboard(
            JSON.stringify((content as JsonCanvasContent).value, null, 2),
          );
        }
      }, [content]);

      return (
        <AttachmentCanvas
          isOpen={isOpen}
          isLoading={isLoading}
          onClose={closeCanvas}
          content={content}
          fileName={fileName}
          labels={{
            ariaLabel,
            closeLabel,
            downloadLabel,
            copyTextLabel,
            copiedTextLabel,
            copyMarkdownLabel,
            copiedMarkdownLabel,
            copyJsonLabel,
            copiedJsonLabel,
            unsupportedLabel,
            loadErrorLabel,
            forbiddenErrorLabel,
            htmlFrameBlockedLabel,
            htmlOpenInNewTabLabel,
            htmlViewSourceLabel,
            htmlViewRenderedLabel,
            pdfThumbnailsLabel,
            pdfShowThumbnailsLabel,
            pdfHideThumbnailsLabel,
            pdfPageNumberLabel,
            pdfContentLoadingLabel,
            pdfContentErrorLabel,
            pdfContentRetryLabel,
            xlsxFormulaLabel,
            codeContentLoadingLabel,
            codeContentErrorLabel,
            codeContentRetryLabel,
            tableCopyLabel,
            tableCopiedLabel,
            tableDownloadCsvLabel,
            ooxmlHighlightsLabel,
            ooxmlHighlightNavigatedLabel,
          }}
          onDownload={handleDownload}
          onCopyText={
            content.type === AttachmentContentType.PlainText ||
            content.type === AttachmentContentType.Code
              ? handleCopyText
              : undefined
          }
          onCopyMarkdown={
            content.type === AttachmentContentType.Markdown
              ? handleCopyMarkdown
              : undefined
          }
          onCopyJson={
            content.type === AttachmentContentType.Json
              ? handleCopyJson
              : undefined
          }
          tableDownloadFilename={tableDownloadFilename}
          isMobile={isMobile}
          defaultWidth={defaultWidth}
          maxWidth={maxWidth}
          codeBlockTheme={codeBlockTheme}
          configurePdfWorker={configurePdfWorker}
        />
      );
    },
  )

export interface AttachmentCanvasContainerProps {
  /** User-visible strings. All fields have English defaults. */
  labels?: AttachmentCanvasLabels;
  /** Whether the viewport is in mobile breakpoint — disables drag-to-resize. Defaults to `false`. */
  isMobile?: boolean;
  /** Initial panel width in pixels. When omitted, SidebarPanel uses its own default. */
  defaultWidth?: number;
  /** Maximum panel width in pixels. Constrains drag-to-resize so the chat area is never fully hidden. */
  maxWidth?: number;
  /** Syntax highlight color theme forwarded to MarkdownRenderer code blocks. */
  codeBlockTheme?: CodeBlockTheme;
  /** Filename used when downloading a `MarkdownTable`'s content as CSV. Defaults to `'table.csv'`. */
  tableDownloadFilename?: string;
  /**
   * Configures `pdfjs-dist`'s worker (`GlobalWorkerOptions.workerSrc`) for the
   * host app. Called once, the first time a PDF attachment is opened, and
   * awaited before the viewer mounts. Concurrent PDF opens share one
   * in-flight call; a successful call is memoized so later opens never
   * repeat it. A rejected call is not cached — the next PDF open (or a
   * subsequent retry) invokes it again. When omitted,
   * `@epam/pdf-highlighter-kit`'s own CDN-hosted worker fallback is used
   * instead, so PDF rendering still works, just without the host's own
   * bundled worker asset.
   */
  configurePdfWorker?: () => void | Promise<void>;
}

CodeContent: FC<CodeContentProps> = memo(
  ({ content, codeBlockTheme = CodeBlockTheme.Light, labels }) => {
    const { text, language } = content;
    const isPlain = language == null || language === 'plaintext';
    const syntaxTheme = SYNTAX_THEME[codeBlockTheme];
    const isLightTheme = codeBlockTheme === CodeBlockTheme.Light;

    const [retryKey, setRetryKey] = useState(0);
    const LazySyntaxHighlighter = useMemo(createLazySyntaxHighlighter, [
      retryKey,
    ]);
    const handleRetry = useCallback(() => {
      setRetryKey((key) => key + 1);
    }, []);

    const plainTextFallback = (
      <pre className="whitespace-pre-wrap break-words p-4">{text}</pre>
    );

    return (
      <div
        dir="ltr"
        className={mergeClasses(
          'h-full overflow-auto',
          styles.container,
          isLightTheme && styles.containerLight,
        )}
      >
        {isPlain ? (
          plainTextFallback
        ) : (
          <LazyContentBoundary
            retryKey={retryKey}
            onRetry={handleRetry}
            pendingContent={plainTextFallback}
            errorContent={plainTextFallback}
            labels={labels}
          >
            <LazySyntaxHighlighter
              language={language}
              style={syntaxTheme}
              customStyle={{
                margin: 0,
                borderRadius: 0,
                background: 'transparent',
                fontSize: 14,
                lineHeight: 1.5,
                padding: '16px',
                letterSpacing: 0,
              }}
              wrapLongLines
            >
              {text}
            </LazySyntaxHighlighter>
          </LazyContentBoundary>
        )}
      </div>
    );
  },
)

