McpAppCanvasRenderer: FC<McpAppCanvasRendererProps> = ({
  content,
  errorLabel = 'Failed to load app',
  onAppInfo,
}) => {
  const [status, setStatus] = useState<RendererStatus>(RendererStatus.Loading);
  const { html, sandboxUrl, toolInput, toolResult, hostContext } = content;
  /*
   * `AppFrame` re-creates its sandbox iframe whenever `sandbox.url` changes
   * identity (its mount effect depends on the object itself, not just
   * `.href`) — a literal `new URL(sandboxUrl)` on every render churns the
   * iframe on every re-render of a host that doesn't memoize `content`
   * itself (e.g. a preview mounted continuously alongside a streaming
   * message), which can keep the app stuck reinitializing and never reach
   * `onSizeChanged`. Memoized here so identity only changes with the URL.
   */
  const sandbox = useMemo(() => ({ url: new URL(sandboxUrl) }), [sandboxUrl]);
  const isFullscreen = hostContext?.displayMode === 'fullscreen';

  const containerRef = useRef<HTMLDivElement>(null);
  const [containerSize, setContainerSize] = useState<{
    width: number;
    height: number;
  }>();

  /*
   * Reports the real, live pixel size of this component's own container
   * (e.g. the resizable attachment canvas panel) to the mounted app via
   * `hostContext.containerDimensions` — the bridge sends a
   * `ui/notifications/host-context-changed` notification whenever
   * `setHostContext` is called with changed values, so a resize here
   * (drag-resizing the panel, window resize) reaches a well-behaved app
   * live, not just once at mount.
   */
  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const observer = new ResizeObserver(([entry]) => {
      if (!entry) return;
      const { width, height } = entry.contentRect;
      setContainerSize({
        width: Math.round(width),
        height: Math.round(height),
      });
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  const liveHostContext = useMemo(() => {
    if (hostContext == null || containerSize == null) return hostContext;
    return { ...hostContext, containerDimensions: containerSize };
  }, [hostContext, containerSize]);

  const { appBridge, hasFailed } = useMcpAppBridge(
    content,
    containerRef,
    liveHostContext,
  );

  const isErrored = hasFailed || status === RendererStatus.Error;

  return (
    <div
      ref={containerRef}
      className={mergeClasses(
        /* `min-h-[200px]` is a Loading-overlay floor, not the intended size — see design.md D19. */
        'relative h-full min-h-[200px] w-full',
        isFullscreen && styles.fullscreenFrame,
      )}
    >
      {appBridge != null && (
        <AppFrame
          html={html}
          sandbox={sandbox}
          appBridge={appBridge}
          toolInput={toolInput}
          toolResult={toolResult}
          onSizeChanged={() => setStatus(RendererStatus.Ready)}
          onInitialized={(appInfo) => {
            setStatus(RendererStatus.Ready);
            if (appInfo.appVersion != null) onAppInfo?.(appInfo.appVersion);
          }}
          onError={() => setStatus(RendererStatus.Error)}
        />
      )}
      {!isErrored && status === RendererStatus.Loading && (
        <div
          className={mergeClasses(
            'absolute inset-0 flex flex-col items-center justify-center gap-2',
            styles.loadingOverlay,
          )}
        >
          <Spinner />
        </div>
      )}
      {isErrored && (
        <div className="absolute inset-0 flex flex-col items-center justify-center gap-2">
          <IconAlertTriangle
            size={60}
            stroke={DIAL_KIT_ICON_STROKE}
            aria-hidden
            className={styles.errorIcon}
          />
          <p
            role="alert"
            className={mergeClasses('text-center', styles.statusLabel)}
          >
            {errorLabel}
          </p>
        </div>
      )}
    </div>
  );
}

export interface McpAppCanvasRendererProps {
  /** MCP App content to render. */
  content: McpAppCanvasContent;
  /** Message shown when the app fails to initialize. Defaults to `'Failed to load app'`. */
  errorLabel?: string;
  /** Called once the mounted app completes its `ui/initialize` handshake, with its declared name/version. Omitted when the app didn't declare an `appInfo`. */
  onAppInfo?: (appInfo: Implementation) => void;
}

AttachmentCanvasProvider = ({
  children,
}: {
  children: ReactNode;
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [content, setContent] =
    useState<AttachmentCanvasContent>(EMPTY_CONTENT);
  const [fileName, setFileName] = useState<string | undefined>(undefined);
  const [attachmentId, setAttachmentId] = useState<string | undefined>(
    undefined,
  );

  const openCanvasLoading = useCallback(
    (newFileName?: string, newAttachmentId?: string) => {
      setFileName(newFileName);
      setAttachmentId(newAttachmentId);
      setIsLoading(true);
      setIsOpen(true);
    },
    [],
  );

  const openCanvas = useCallback(
    (
      newContent: AttachmentCanvasContent,
      newFileName?: string,
      newAttachmentId?: string,
    ) => {
      setContent(newContent);
      setFileName(newFileName);
      setAttachmentId(newAttachmentId);
      setIsLoading(false);
      setIsOpen(true);
    },
    [],
  );

  const closeCanvas = useCallback(() => {
    setContent(EMPTY_CONTENT);
    setIsOpen(false);
    setIsLoading(false);
    setAttachmentId(undefined);
  }, []);

  /* Revokes the outgoing content's object URL whenever it is replaced by new
   * content, and on unmount — otherwise every opened image/PDF blob URL leaks
   * for the lifetime of the page. */
  useEffect(() => {
    return () => {
      const url = getRevocableObjectUrl(content);
      if (url != null) URL.revokeObjectURL(url);
    };
  }, [content]);

  return (
    <AttachmentCanvasContext.Provider
      value={useMemo(
        () => ({
          isOpen,
          isLoading,
          content,
          fileName,
          attachmentId,
          openCanvasLoading,
          openCanvas,
          closeCanvas,
        }),
        [
          isOpen,
          isLoading,
          content,
          fileName,
          attachmentId,
          openCanvasLoading,
          openCanvas,
          closeCanvas,
        ],
      )}
    >
      {children}
    </AttachmentCanvasContext.Provider>
  );
}

useAttachmentCanvas = (): AttachmentCanvasContextValue => {
  const value = useContext(AttachmentCanvasContext);
  if (!value) {
    throw new Error(
      'useAttachmentCanvas must be used within an AttachmentCanvasProvider',
    );
  }
  return value;
}

export interface AttachmentCanvasContextValue {
  /** Whether the canvas panel is currently open. */
  isOpen: boolean;
  /** Whether the panel is open but content is still being resolved (shows a spinner). */
  isLoading: boolean;
  /** Content currently displayed in the canvas. */
  content: AttachmentCanvasContent;
  /** File name shown in the canvas header. */
  fileName: string | undefined;
  /** ID of the attachment currently displayed in the canvas, if any. */
  attachmentId: string | undefined;
  /** Open the canvas immediately in a loading state before content has resolved. */
  openCanvasLoading: (fileName?: string, attachmentId?: string) => void;
  /** Open the canvas with the given content and optional file name. */
  openCanvas: (
    content: AttachmentCanvasContent,
    fileName?: string,
    attachmentId?: string,
  ) => void;
  /** Close the canvas. */
  closeCanvas: () => void;
}

useOpenAttachmentCanvas = (
  resolvers: UseOpenAttachmentCanvasResolvers,
  options: UseOpenAttachmentCanvasOptions,
): { openAttachmentCanvas: OpenAttachmentCanvas } => {
  const { openCanvas, openCanvasLoading, closeCanvas } = useAttachmentCanvas();
  const { customVisualizers, themeId, onBeforeOpen } = options;

  const openFileCanvas = useCallback(
    async (
      attachment: DisplayAttachment,
      canvasAttachmentId: string | undefined,
      commitCanvas: CommitCanvasContent,
    ): Promise<boolean> => {
      if (attachment.url == null && attachment.referenceUrl != null) {
        const pdfContent = resolvers.resolveReferencePdfContent(attachment);
        if (pdfContent != null) {
          return commitCanvas(pdfContent, attachment.name, canvasAttachmentId);
        }
      }

      const contentType = attachment.contentType.toLowerCase();

      const visualizerEntry = findVisualizerForMime(
        contentType,
        customVisualizers,
      );
      if (visualizerEntry != null) {
        const content = await resolvers.resolveVisualizerContent(
          attachment,
          visualizerEntry,
          themeId,
        );
        if (content != null) {
          return commitCanvas(content, attachment.name, canvasAttachmentId);
        }
      }

      if (!contentType && attachment.data != null) {
        const content = await resolvers.resolveTextContent(attachment);
        if (content != null) {
          return commitCanvas(content, attachment.name, canvasAttachmentId);
        }
      }

      const mimeOoxmlFileType = getOoxmlFileType('', contentType);
      if (mimeOoxmlFileType != null) {
        const content = await resolvers.resolveOoxmlContent(
          attachment,
          mimeOoxmlFileType,
        );
        return commitCanvas(
          content ??
            createUnsupportedCanvasContent(
              resolvers.resolveContentUrl(attachment),
            ),
          attachment.name,
          canvasAttachmentId,
        );
      }

      switch (contentType) {
        case MIMEType.PDF: {
          const content = await resolvers.resolvePdfContent(attachment);
          return commitCanvas(
            content ??
              createUnsupportedCanvasContent(
                resolvers.resolveContentUrl(attachment),
              ),
            attachment.name,
            canvasAttachmentId,
          );
        }
        case MIMEType.Markdown: {
          const content = await resolvers.resolveMarkdownContent(attachment);
          return commitCanvas(
            content ??
              createUnsupportedCanvasContent(
                resolvers.resolveContentUrl(attachment),
              ),
            attachment.name,
            canvasAttachmentId,
          );
        }
        case MIMEType.JSON: {
          const content = await resolvers.resolveJsonContent(attachment);
          return commitCanvas(
            content ??
              createUnsupportedCanvasContent(
                resolvers.resolveContentUrl(attachment),
              ),
            attachment.name,
            canvasAttachmentId,
          );
        }
      }

      const fileName = attachment.name ?? '';
      const dotIdx = fileName.lastIndexOf('.');
      const ext = dotIdx !== -1 ? fileName.slice(dotIdx + 1).toLowerCase() : '';

      const extensionOoxmlFileType = getOoxmlFileType(fileName);
      if (extensionOoxmlFileType != null) {
        const content = await resolvers.resolveOoxmlContent(
          attachment,
          extensionOoxmlFileType,
        );
        return commitCanvas(
          content ??
            createUnsupportedCanvasContent(
              resolvers.resolveContentUrl(attachment),
            ),
          attachment.name,
          canvasAttachmentId,
        );
      }

      switch (ext) {
        case FileExtension.Markdown:
        case FileExtension.MarkdownAlt: {
          const content = await resolvers.resolveMarkdownContent(attachment);
          if (content == null) return false;
          return commitCanvas(content, attachment.name, canvasAttachmentId);
        }
        case FileExtension.JSON: {
          const content = await resolvers.resolveJsonContent(attachment);
          if (content == null) return false;
          return commitCanvas(content, attachment.name, canvasAttachmentId);
        }
        case FileExtension.PDF: {
          const content = await resolvers.resolvePdfContent(attachment);
          if (content == null) return false;
          return commitCanvas(content, attachment.name, canvasAttachmentId);
        }
      }

      /*
       * A cited source's `name` is its title, which usually carries no file
       * extension, so the URL's own file name has to be consulted as well —
       * otherwise an external `.html` source falls into the Unsupported
       * branch below instead of opening in the iframe.
       */
      const isHtmlSource =
        (attachment.name != null && isHtmlPreviewable(attachment.name)) ||
        (attachment.url != null &&
          isHtmlPreviewable(getUrlFileName(attachment.url)));

      if (
        attachment.name != null &&
        !isTextPreviewable(attachment.name) &&
        !isHtmlSource
      ) {
        return commitCanvas(
          createUnsupportedCanvasContent(
            resolvers.resolveContentUrl(attachment),
          ),
          attachment.name,
          canvasAttachmentId,
        );
      }

      if (isHtmlSource) {
        const content = await resolvers.resolveHtmlContent(attachment);
        if (content != null) {
          return commitCanvas(content, attachment.name, canvasAttachmentId);
        }
        if (!resolvers.hasTextSource(attachment)) {
          /* External HTML URL: nothing to fetch, so the iframe loads it directly. */
          if (attachment.url == null) return false;
          return commitCanvas(
            { type: AttachmentContentType.Html, url: attachment.url },
            attachment.name,
            canvasAttachmentId,
          );
        }
        /*
         * The text was fetched and then rejected — currently only by the
         * srcdoc size gate. That is an unsupported preview, not a page the
         * browser refused to frame, so it must not fall through to the
         * url-only branch above.
         */
        return commitCanvas(
          createUnsupportedCanvasContent(
            resolvers.resolveContentUrl(attachment),
          ),
          attachment.name,
          canvasAttachmentId,
        );
      }

      const content = await resolvers.resolveCodeContent(
        attachment,
        extensionToLanguage(ext),
      );
      if (content == null) return false;
      return commitCanvas(content, attachment.name, canvasAttachmentId);
    },
    [customVisualizers, themeId, resolvers],
  );

  const openAttachmentCanvas = useCallback(
    async (
      attachment: DisplayAttachment,
      /*
       * DisplayAttachment.id is derived from content (url/data/title), so the
       * same id can recur across different messages (e.g. the same file
       * attached twice). Callers that need to track which specific tile
       * opened the canvas (to highlight it as selected) pass a caller-scoped
       * key here instead of relying on the content-derived id.
       */
      canvasAttachmentId: string | undefined = attachment.id,
      shouldCommit?: ShouldCommitCanvas,
    ): Promise<boolean> => {
      const canCommit = () => shouldCommit == null || shouldCommit();

      const commitCanvas: CommitCanvasContent = (content, fileName, id) => {
        if (!canCommit()) {
          /* The canvas revokes only what it actually held, so a payload that
             never reaches it has to be released here. */
          releaseCanvasContent(content);
          return false;
        }
        openCanvas(content, fileName, id);
        return true;
      };

      switch (attachment.type) {
        case AttachmentType.Image: {
          const content = resolvers.resolveImageContent(attachment);
          if (content == null) return false;
          onBeforeOpen?.();
          /* Synchronous: there is no await between the caller's decision and
             this write, so no staleness is possible. */
          openCanvas(content, attachment.name, canvasAttachmentId);
          return true;
        }
        case AttachmentType.Audio: {
          const url = attachment.playUrl ?? attachment.url;
          if (url == null) return false;
          openCanvas(
            {
              type: AttachmentContentType.Audio,
              url,
              mimeType: attachment.contentType || undefined,
            },
            attachment.name,
            canvasAttachmentId,
          );
          return true;
        }
        case AttachmentType.File: {
          onBeforeOpen?.();
          openCanvasLoading(attachment.name, canvasAttachmentId);
          const opened = await openFileCanvas(
            attachment,
            canvasAttachmentId,
            commitCanvas,
          );
          /* `canCommit` is re-checked here rather than reused from the commit
             above: closing is itself a canvas write, and a request that has
             stopped owning the canvas must not close whatever took it over. */
          if (!opened && canCommit()) closeCanvas();
          return opened;
        }
        case AttachmentType.Pasted:
        case AttachmentType.Prompt: {
          onBeforeOpen?.();
          openCanvasLoading(attachment.name, canvasAttachmentId);
          const content = await resolvers.resolveTextContent(attachment);
          if (content == null) {
            if (canCommit()) closeCanvas();
            return false;
          }
          return commitCanvas(content, attachment.name, canvasAttachmentId);
        }
        default:
          return false;
      }
    },
    [
      openCanvas,
      openCanvasLoading,
      closeCanvas,
      onBeforeOpen,
      openFileCanvas,
      resolvers,
    ],
  );

  return { openAttachmentCanvas };
}

export type OpenAttachmentCanvas = (
  attachment: DisplayAttachment,
  canvasAttachmentId?: string,
  shouldCommit?: ShouldCommitCanvas,
) => Promise<boolean>;

export interface UseOpenAttachmentCanvasOptions {
  /** Registry of custom visualizers matched by MIME type ahead of PDF/Markdown/JSON routing. */
  customVisualizers: CustomVisualizer[];
  /** Active theme id forwarded to a matched custom visualizer's layout. */
  themeId?: string;
  /** Called before the canvas opens for an image, file, pasted, or prompt attachment — never for audio. Lets the host close other panels first. */
  onBeforeOpen?: () => void;
}

export interface UseOpenAttachmentCanvasResolvers {
  /** Resolves an image attachment's displayable URL. Returns `null` if unavailable. */
  resolveImageContent(attachment: DisplayAttachment): ImageCanvasContent | null;
  /** Resolves an attachment's plain-text content. Returns `null` if unavailable. */
  resolveTextContent(
    attachment: DisplayAttachment,
  ): Promise<PlainTextCanvasContent | ErrorCanvasContent | null>;
  /** Resolves an attachment's Markdown content. Returns `null` if unavailable. */
  resolveMarkdownContent(
    attachment: DisplayAttachment,
  ): Promise<MarkdownCanvasContent | ErrorCanvasContent | null>;
  /** Resolves an attachment's syntax-highlighted code content, given an optional language hint. Returns `null` if unavailable. */
  resolveCodeContent(
    attachment: DisplayAttachment,
    language?: string,
  ): Promise<CodeCanvasContent | ErrorCanvasContent | null>;
  /** Resolves an attachment's HTML content. Returns `null` if unavailable or rejected (e.g. exceeded a size limit). */
  resolveHtmlContent(
    attachment: DisplayAttachment,
  ): Promise<HtmlCanvasContent | ErrorCanvasContent | null>;
  /** Resolves an attachment's PDF content. Returns `null` if unavailable. */
  resolvePdfContent(
    attachment: DisplayAttachment,
  ): Promise<PdfCanvasContent | ErrorCanvasContent | null>;
  /** Resolves an attachment's OOXML or CSV content for the given `@silurus/ooxml` format. Returns `null` if unavailable. */
  resolveOoxmlContent(
    attachment: DisplayAttachment,
    format: OoxmlFileType,
  ): Promise<OoxmlCanvasContent | ErrorCanvasContent | null>;
  /** Resolves an attachment's JSON content, falling back to plain text when the payload is not valid JSON. Returns `null` if unavailable. */
  resolveJsonContent(
    attachment: DisplayAttachment,
  ): Promise<
    JsonCanvasContent | PlainTextCanvasContent | ErrorCanvasContent | null
  >;
  /** Resolves an attachment against a matched custom-visualizer registry entry. Returns `null` when the payload cannot be fetched. */
  resolveVisualizerContent(
    attachment: DisplayAttachment,
    visualizer: CustomVisualizer,
    themeId?: string,
  ): Promise<VisualizerCanvasContent | null>;
  /** Resolves a reference-only attachment's `referenceUrl` (optionally carrying a page anchor) into PDF content. Returns `null` when the reference does not target a PDF. */
  resolveReferencePdfContent(
    attachment: DisplayAttachment,
  ): PdfCanvasContent | null;
  /** Resolves the attachment's downloadable URL, used for `Unsupported` content and as the HTML content's fallback `url`. */
  resolveContentUrl(attachment: DisplayAttachment): string | undefined;
  /**
   * Whether the attachment carries a text source `resolveHtmlContent`/
   * `resolveTextContent` etc. can fetch from (inline data, a host-resolved
   * download URL, or a locally-picked file). Used to distinguish "nothing to
   * fetch" from "fetched and rejected" when an HTML resolver returns `null`.
   */
  hasTextSource(attachment: DisplayAttachment): boolean;
}

export interface AttachmentCanvasBodyProps {
  /** The attachment content to render. */
  content: AttachmentCanvasContent;
  /** When `true`, renders a loading spinner instead of content. Defaults to `false`. */
  isLoading?: boolean;
  /** File name used for image `alt` text and the audio player's accessible label. */
  fileName?: string;
  /**
   * Whether an `Html` content type renders its raw source instead of the
   * sandboxed rendered view. Ignored for every other content type. Defaults
   * to `false`. The host owns this toggle's state since the corresponding
   * toggle button lives outside this component.
   */
  isHtmlSourceView?: boolean;
  /** User-visible strings for content states (unsupported/error/HTML-blocked messages). */
  labels?: AttachmentCanvasBodyLabels;
  /** Style overrides for the content body. */
  styles?: AttachmentCanvasBodyStyles;
  /** Syntax highlight color theme forwarded to MarkdownRenderer/CodeContent code blocks. */
  codeBlockTheme?: CodeBlockTheme;
  /** Filename used when downloading a `MarkdownTable`'s content as CSV. Defaults to `'table.csv'`. Only relevant when content type is `MarkdownTable`. */
  tableDownloadFilename?: string;
  /** Called once a mounted `McpApp` completes its `ui/initialize` handshake, with its declared name/version. Only relevant when content type is `McpApp`; omitted when the app didn't declare an `appInfo`. */
  onAppInfo?: (appInfo: Implementation) => void;
  /**
   * Fetches a PDF file by URL and returns its bytes as a `Blob`. Used when
   * content type is `Pdf` to load the file before rendering. Defaults to a
   * plain `fetch` if not provided.
   */
  loadPdf?: (url: string) => Promise<Blob>;
  /**
   * Hides the PDF renderer's own title/zoom toolbar row for `Pdf` content —
   * for hosts that render their own header and don't want it duplicated.
   * Ignored for every other content type. Defaults to `false`.
   */
  hidePdfToolbar?: boolean;
  /**
   * Configures `pdfjs-dist`'s worker (`GlobalWorkerOptions.workerSrc`) for the
   * host app. Called once, the first time a PDF attachment is opened, and
   * awaited before the viewer mounts. Concurrent PDF opens share one
   * in-flight call; a successful call is memoized so later opens never
   * repeat it. A rejected call is not cached — the next PDF open (or a
   * subsequent retry) invokes it again. When omitted,
   * `@epam/pdf-highlighter-kit`'s own CDN-hosted worker fallback is used
   * instead, so PDF rendering still works, just without the host's own
   * bundled worker asset.
   */
  configurePdfWorker?: () => void | Promise<void>;
}

