createForbiddenCanvasContent = (
  url?: string,
): ErrorCanvasContent => ({
  type: AttachmentContentType.Error,
  errorType: AttachmentErrorType.Forbidden,
  ...(url != null && { url }),
})

createLoadErrorCanvasContent = (
  url?: string,
): ErrorCanvasContent => ({
  type: AttachmentContentType.Error,
  errorType: AttachmentErrorType.LoadFailed,
  ...(url != null && { url }),
})

createUnsupportedCanvasContent = (
