getOoxmlFileType = (
  name: string,
  mimeType?: string,
): OoxmlFileType | undefined => {
  const normalizedMimeType = mimeType?.split(';', 1)[0].trim().toLowerCase();
  if (normalizedMimeType != null) {
    const mimeMatch = RENDERER_MIME_TO_FILE_TYPE[normalizedMimeType];
    if (mimeMatch != null) return mimeMatch;
  }

  const dot = name.lastIndexOf('.');
  if (dot === -1) return undefined;
  return RENDERER_EXTENSION_TO_FILE_TYPE[name.slice(dot + 1).toLowerCase()];
}

getOoxmlMimeType = (
  name: string,
  mimeType?: string,
): string | undefined => {
  const fileType = getOoxmlFileType(name, mimeType);
  return fileType != null ? RENDERER_FILE_TYPE_TO_MIME[fileType] : undefined;
}

isHtmlPreviewable = (name: string): boolean => {
  const dot = name.lastIndexOf('.');
  if (dot === -1) return false;
  return HTML_EXTENSIONS.has(name.slice(dot + 1).toLowerCase());
}

isTextPreviewable = (name: string): boolean => {
  const dot = name.lastIndexOf('.');
  if (dot === -1) return false;
  return TEXT_EXTENSIONS.has(name.slice(dot + 1).toLowerCase());
}

downloadAttachmentContent = (
  content: AttachmentCanvasContent,
  fileName?: string,
): void => {
  const { url: contentUrl, mimeType: contentMimeType } =
    getContentUrlAndMimeType(content);
  const name = ensureDownloadFilename(
    fileName ?? 'attachment',
    contentUrl,
    contentMimeType,
  );
  switch (content.type) {
    case AttachmentContentType.PlainText:
      if (content.text === '') return;
      triggerBlobDownload(
        new Blob([content.text], { type: MIMEType.Plain }),
        name,
      );
      return;
    case AttachmentContentType.Markdown:
      if (content.text === '') return;
      triggerBlobDownload(
        new Blob([content.text], { type: MIMEType.Markdown }),
        name,
      );
      return;
    case AttachmentContentType.Json:
      triggerBlobDownload(
        new Blob([JSON.stringify(content.value, null, 2)], {
          type: MIMEType.JSON,
        }),
        name,
      );
      return;
    case AttachmentContentType.Image:
    case AttachmentContentType.Audio:
    case AttachmentContentType.Pdf:
    case AttachmentContentType.Ooxml:
      triggerAnchorDownload(content.url, name);
      return;
    case AttachmentContentType.Code:
      if (content.text === '') return;
      triggerBlobDownload(
        new Blob([content.text], { type: MIMEType.Plain }),
        name,
      );
      return;
    case AttachmentContentType.Html:
      if (content.url == null) return;
      triggerAnchorDownload(content.url, name);
      return;
    /* Not downloadable — see `isDownloadable`. */
    case AttachmentContentType.MarkdownTable:
    case AttachmentContentType.Visualizer:
    case AttachmentContentType.McpApp:
      return;
    case AttachmentContentType.Unsupported:
      if (content.url == null) return;
      triggerAnchorDownload(content.url, name);
      return;
    case AttachmentContentType.Error:
      if (!isDownloadable(content) || content.url == null) return;
      triggerAnchorDownload(content.url, name);
      return;
  }
}

isDownloadable = (content: AttachmentCanvasContent): boolean => {
  switch (content.type) {
    case AttachmentContentType.PlainText:
    case AttachmentContentType.Markdown:
    case AttachmentContentType.Json:
    case AttachmentContentType.Image:
    case AttachmentContentType.Audio:
    case AttachmentContentType.Pdf:
    case AttachmentContentType.Ooxml:
    case AttachmentContentType.Code:
      return true;
    case AttachmentContentType.Html:
      return content.url != null;
    /*
     * A standalone table's download action lives in its own inline header
     * (CSV, via its localized table labels), not the generic download button.
     */
    case AttachmentContentType.MarkdownTable:
    case AttachmentContentType.Visualizer:
    case AttachmentContentType.GroupedVisualizer:
    case AttachmentContentType.McpApp:
      return false;
    case AttachmentContentType.Unsupported:
      return content.url != null;
    case AttachmentContentType.Error:
      return (
        content.errorType !== AttachmentErrorType.Forbidden &&
        content.url != null
      );
  }
}

findVisualizerForApplication = (
  applicationId: string | undefined,
  visualizers: ApplicationVisualizerRegistry,
): ApplicationVisualizer | undefined => {
  if (applicationId == null || applicationId === '') {
    return undefined;
  }
  return Object.prototype.hasOwnProperty.call(visualizers, applicationId)
    ? visualizers[applicationId]
    : undefined;
}

findVisualizerForMime = (
  mimeType: string,
  visualizers: CustomVisualizer[],
): CustomVisualizer | undefined => {
  const needle = mimeType.toLowerCase();
  return visualizers.find((entry) =>
    entry.contentType
      .split(',')
      .some(
        (part) => part.trim().toLowerCase() === needle && part.trim() !== '',
      ),
  );
}

partitionAttachmentsForApplicationVisualizer = (
  attachments: DisplayAttachment[],
  visualizer: ApplicationVisualizer,
): ApplicationVisualizerPartition => {
  const declaredMimes = (visualizer.contentType ?? '')
    .split(',')
    .map((part) => part.trim().toLowerCase())
    .filter((part) => part !== '');

  const claimed: DisplayAttachment[] = [];
  const unclaimed: DisplayAttachment[] = [];

  attachments.forEach((attachment) => {
    const hasUrl = attachment.url != null && attachment.url !== '';
    /* No declared MIME list means "every attachment with a URL"; a declared
     * list still requires a URL, because the grouped payload addresses each
     * attachment by absolute URL and has no channel for inline data. */
    const isClaimed =
      hasUrl &&
      (declaredMimes.length === 0 ||
        declaredMimes.includes(attachment.contentType.toLowerCase()));

    if (isClaimed) {
      claimed.push(attachment);
      return;
    }
    unclaimed.push(attachment);
  });

  return { claimed, unclaimed };
}

export interface ApplicationVisualizerPartition {
  /** Attachments the entry claims, to be sent as one grouped payload. In the input's order. */
  claimed: DisplayAttachment[];
  /** Attachments the entry does not claim, to be rendered as ordinary tiles. In the input's order. */
  unclaimed: DisplayAttachment[];
}

