McpAppCanvasRenderer: FC<McpAppCanvasRendererProps> = ({
  content,
  errorLabel = 'Failed to load app',
  onAppInfo,
}) => {
  const [status, setStatus] = useState<RendererStatus>(RendererStatus.Loading);
  const { html, sandboxUrl, toolInput, toolResult, hostContext } = content;
  /*
   * `AppFrame` re-creates its sandbox iframe whenever `sandbox.url` changes
   * identity (its mount effect depends on the object itself, not just
   * `.href`) — a literal `new URL(sandboxUrl)` on every render churns the
   * iframe on every re-render of a host that doesn't memoize `content`
   * itself (e.g. a preview mounted continuously alongside a streaming
   * message), which can keep the app stuck reinitializing and never reach
   * `onSizeChanged`. Memoized here so identity only changes with the URL.
   */
  const sandbox = useMemo(() => ({ url: new URL(sandboxUrl) }), [sandboxUrl]);
  const isFullscreen = hostContext?.displayMode === 'fullscreen';

  const containerRef = useRef<HTMLDivElement>(null);
  const [containerSize, setContainerSize] = useState<{
    width: number;
    height: number;
  }>();

  /*
   * Reports the real, live pixel size of this component's own container
   * (e.g. the resizable attachment canvas panel) to the mounted app via
   * `hostContext.containerDimensions` — the bridge sends a
   * `ui/notifications/host-context-changed` notification whenever
   * `setHostContext` is called with changed values, so a resize here
   * (drag-resizing the panel, window resize) reaches a well-behaved app
   * live, not just once at mount.
   */
  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const observer = new ResizeObserver(([entry]) => {
      if (!entry) return;
      const { width, height } = entry.contentRect;
      setContainerSize({
        width: Math.round(width),
        height: Math.round(height),
      });
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  const liveHostContext = useMemo(() => {
    if (hostContext == null || containerSize == null) return hostContext;
    return { ...hostContext, containerDimensions: containerSize };
  }, [hostContext, containerSize]);

  const { appBridge, hasFailed } = useMcpAppBridge(
    content,
    containerRef,
    liveHostContext,
  );

  const isErrored = hasFailed || status === RendererStatus.Error;

  return (
    <div
      ref={containerRef}
      className={mergeClasses(
        /* `min-h-[200px]` is a Loading-overlay floor, not the intended size — see design.md D19. */
        'relative h-full min-h-[200px] w-full',
        isFullscreen && styles.fullscreenFrame,
      )}
    >
      {appBridge != null && (
        <AppFrame
          html={html}
          sandbox={sandbox}
          appBridge={appBridge}
          toolInput={toolInput}
          toolResult={toolResult}
          onSizeChanged={() => setStatus(RendererStatus.Ready)}
          onInitialized={(appInfo) => {
            setStatus(RendererStatus.Ready);
            if (appInfo.appVersion != null) onAppInfo?.(appInfo.appVersion);
          }}
          onError={() => setStatus(RendererStatus.Error)}
        />
      )}
      {!isErrored && status === RendererStatus.Loading && (
        <div
          className={mergeClasses(
            'absolute inset-0 flex flex-col items-center justify-center gap-2',
            styles.loadingOverlay,
          )}
        >
          <Spinner />
        </div>
      )}
      {isErrored && (
        <div className="absolute inset-0 flex flex-col items-center justify-center gap-2">
          <IconAlertTriangle
            size={60}
            stroke={DIAL_KIT_ICON_STROKE}
            aria-hidden
            className={styles.errorIcon}
          />
          <p
            role="alert"
            className={mergeClasses('text-center', styles.statusLabel)}
          >
            {errorLabel}
          </p>
        </div>
      )}
    </div>
  );
}

AttachmentCanvasProvider = ({
  children,
}: {
  children: ReactNode;
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [content, setContent] =
    useState<AttachmentCanvasContent>(EMPTY_CONTENT);
  const [fileName, setFileName] = useState<string | undefined>(undefined);
  const [attachmentId, setAttachmentId] = useState<string | undefined>(
    undefined,
  );

  const openCanvasLoading = useCallback(
    (newFileName?: string, newAttachmentId?: string) => {
      setFileName(newFileName);
      setAttachmentId(newAttachmentId);
      setIsLoading(true);
      setIsOpen(true);
    },
    [],
  );

  const openCanvas = useCallback(
    (
      newContent: AttachmentCanvasContent,
      newFileName?: string,
      newAttachmentId?: string,
    ) => {
      setContent(newContent);
      setFileName(newFileName);
      setAttachmentId(newAttachmentId);
      setIsLoading(false);
      setIsOpen(true);
    },
    [],
  );

  const closeCanvas = useCallback(() => {
    setContent(EMPTY_CONTENT);
    setIsOpen(false);
    setIsLoading(false);
    setAttachmentId(undefined);
  }, []);

  /* Revokes the outgoing content's object URL whenever it is replaced by new
   * content, and on unmount — otherwise every opened image/PDF blob URL leaks
   * for the lifetime of the page. */
  useEffect(() => {
    return () => {
      const url = getRevocableObjectUrl(content);
      if (url != null) URL.revokeObjectURL(url);
    };
  }, [content]);

  return (
    <AttachmentCanvasContext.Provider
      value={useMemo(
        () => ({
          isOpen,
          isLoading,
          content,
          fileName,
          attachmentId,
          openCanvasLoading,
          openCanvas,
          closeCanvas,
        }),
        [
          isOpen,
          isLoading,
          content,
          fileName,
          attachmentId,
          openCanvasLoading,
          openCanvas,
          closeCanvas,
        ],
      )}
    >
      {children}
    </AttachmentCanvasContext.Provider>
  );
}

useAttachmentCanvas = (): AttachmentCanvasContextValue => {
  const value = useContext(AttachmentCanvasContext);
  if (!value) {
    throw new Error(
